/**
 * Ambient audio, synthesised on the device.
 *
 * Design rules, all of which come from the evidence review summarised in
 * `AUDIO-NOTES.md` and are enforced by `src/audio/audio.test.ts`:
 *
 *  - Nothing is fetched. Every sound is generated by oscillators and a noise
 *    buffer, so the app keeps its "no third-party requests" promise.
 *  - Nothing plays until the user asks for it, from their own click. No
 *    autoplay, no starting from an effect or a timer.
 *  - The starting level is quiet (a digital gain of about 0.05–0.1, not a
 *    claim about the sound pressure at your ear) and volume is independent of
 *    the system volume.
 *  - Transitions ramp; sources are never cut mid-waveform, which is what
 *    produces clicks.
 *  - The context is suspended when the tab is hidden and never restarted
 *    silently afterwards.
 *  - Chimes are decoration. Every one of them has a visible equivalent, so
 *    nothing depends on hearing them.
 */

export type SceneId = 'rain' | 'tide' | 'night' | 'breath';

export interface Scene {
  id: SceneId;
  name: string;
  blurb: string;
  /** What the evidence does and does not support. Shown in the UI. */
  evidence: string;
}

export interface AudioSettings {
  /** Ambience on or off. Off until the user turns it on. */
  enabled: boolean;
  scene: SceneId;
  /** 0–1 from the slider. Never treated as a dB level. */
  volume: number;
  /** Quiet interaction cues. */
  chimes: boolean;
}

export const DEFAULT_SETTINGS: AudioSettings = {
  enabled: false,
  scene: 'rain',
  volume: 0.55,
  chimes: true,
};

export const SCENES: Scene[] = [
  {
    id: 'rain',
    name: 'Rain on a window',
    blurb: 'Bright, even hiss with a slow shift in brightness.',
    evidence:
      'Broadband sound masks other noise, which some people find easier to work near. A meta-analysis found a small benefit for attention in ADHD groups and a small cost for everyone else, so this is a preference, not an enhancer.',
  },
  {
    id: 'tide',
    name: 'Slow tide',
    blurb: 'Low, rounded wash that swells about every fifteen seconds.',
    evidence:
      'Nature sounds sped up skin-conductance recovery after a stress task in one small lab study (Alvarsson et al., 2010); high-frequency heart-rate variability showed no effect. Treat it as pleasant, not as treatment.',
  },
  {
    id: 'night',
    name: 'Night drone',
    blurb: 'Two soft oscillators a fifth apart, no melody, barely moving.',
    evidence:
      'Steady, unchanging sound is easy to ignore, which is the point. There is no evidence that any single frequency is therapeutic, and this one is an ordinary musical interval chosen by ear.',
  },
  {
    id: 'breath',
    name: 'Breathing pace',
    blurb: 'A swell every ten seconds — six breaths a minute.',
    evidence:
      'Slow paced breathing around six breaths a minute has been studied for heart-rate variability and perceived stress (Chaitanya et al., 2022; Fuchs et al., 2018) in small trials. This is a pace to try, not a treatment, and you can breathe normally instead.',
  },
];

export function sceneById(id: SceneId): Scene {
  return SCENES.find((scene) => scene.id === id) ?? (SCENES[0] as Scene);
}

export function isSceneId(value: unknown): value is SceneId {
  return typeof value === 'string' && SCENES.some((scene) => scene.id === value);
}

/** Hard ceiling on digital gain. Quiet by design, not a safety guarantee. */
export const MAX_GAIN = 0.2;
export const FADE_IN = 1.4;
export const FADE_OUT = 0.8;
export const RAMP_TAU = 0.08;

export function clampVolume(value: unknown): number {
  const number = typeof value === 'number' && Number.isFinite(value) ? value : DEFAULT_SETTINGS.volume;
  return Math.min(1, Math.max(0, number));
}

/** Perceptual-ish curve: 0 stays silent, 1 stays below MAX_GAIN. */
export function gainForVolume(volume: number): number {
  const clamped = clampVolume(volume);
  return MAX_GAIN * clamped * clamped;
}

/** Coerce anything that came out of storage into safe settings. */
export function normalizeSettings(input: unknown): AudioSettings {
  if (typeof input !== 'object' || input === null) return { ...DEFAULT_SETTINGS };
  const raw = input as Record<string, unknown>;
  return {
    enabled: raw.enabled === true,
    scene: isSceneId(raw.scene) ? raw.scene : DEFAULT_SETTINGS.scene,
    volume: clampVolume(raw.volume),
    chimes: raw.chimes !== false,
  };
}

export type ChimeKind = 'soft' | 'warm' | 'release' | 'confirm';

interface ChimeSpec {
  /** Ordinary musical pitches in hertz, not "healing frequencies". */
  partials: Array<{ hz: number; gain: number }>;
  decay: number;
}

export const CHIMES: Record<ChimeKind, ChimeSpec> = {
  soft: { partials: [{ hz: 587.33, gain: 0.5 }, { hz: 880, gain: 0.18 }], decay: 0.34 },
  warm: { partials: [{ hz: 440, gain: 0.5 }, { hz: 659.25, gain: 0.2 }], decay: 0.42 },
  confirm: { partials: [{ hz: 523.25, gain: 0.45 }, { hz: 783.99, gain: 0.22 }], decay: 0.3 },
  release: { partials: [{ hz: 392, gain: 0.45 }, { hz: 587.33, gain: 0.16 }], decay: 0.5 },
};

/** Peak gain of any chime, as a fraction of the master level. */
export function chimePeak(kind: ChimeKind): number {
  return CHIMES[kind].partials.reduce((total, partial) => total + partial.gain, 0);
}

export type EngineState = 'idle' | 'starting' | 'running' | 'suspended' | 'unsupported' | 'error';

export interface EngineSnapshot {
  state: EngineState;
  contextState: string;
  scene: SceneId | null;
  volume: number;
  gain: number;
  chimes: boolean;
  meter: number;
  sampleRate: number;
  hiddenPause: boolean;
  /** How many cues have been played. Lets a test prove the wiring, not the sound. */
  chimesPlayed: number;
}

interface BuiltScene {
  sources: AudioScheduledSourceNode[];
  gain: GainNode;
  /** Everything that must be disconnected when the scene is torn down. */
  nodes: AudioNode[];
}

const NOISE_SECONDS = 3;

function makeNoiseBuffer(context: AudioContext): AudioBuffer {
  const length = Math.floor(context.sampleRate * NOISE_SECONDS);
  const buffer = context.createBuffer(1, length, context.sampleRate);
  const data = buffer.getChannelData(0);
  let last = 0;
  for (let i = 0; i < length; i += 1) {
    const white = Math.random() * 2 - 1;
    // One-pole low pass on the source: flatter and less hissy than raw white,
    // which makes the filters downstream do less work.
    last = 0.98 * last + 0.02 * white;
    data[i] = (white + last * 2.2) * 0.5;
  }
  return buffer;
}

function buildScene(context: AudioContext, buffer: AudioBuffer, scene: SceneId): BuiltScene {
  const sources: AudioScheduledSourceNode[] = [];
  const nodes: AudioNode[] = [];
  const gain = context.createGain();
  gain.gain.value = 0;
  nodes.push(gain);

  const noise = (filter: BiquadFilterNode) => {
    const source = context.createBufferSource();
    source.buffer = buffer;
    source.loop = true;
    source.connect(filter);
    source.start();
    sources.push(source);
    nodes.push(filter);
    return source;
  };

  if (scene === 'rain' || scene === 'tide') {
    const highpass = context.createBiquadFilter();
    highpass.type = 'highpass';
    highpass.frequency.value = scene === 'rain' ? 320 : 60;
    const lowpass = context.createBiquadFilter();
    lowpass.type = 'lowpass';
    lowpass.frequency.value = scene === 'rain' ? 5200 : 900;
    lowpass.Q.value = scene === 'rain' ? 0.6 : 0.9;
    noise(highpass).connect(lowpass).connect(gain);

    // Slow movement so the scene never sounds like a frozen loop.
    const sweep = context.createOscillator();
    sweep.frequency.value = scene === 'rain' ? 0.037 : 0.021;
    const sweepDepth = context.createGain();
    sweepDepth.gain.value = scene === 'rain' ? 1400 : 320;
    sweep.connect(sweepDepth).connect(lowpass.frequency);
    sweep.start();
    sources.push(sweep);

    if (scene === 'tide') {
      // The swell: roughly a fifteen second cycle, twice the sweep rate.
      const swell = context.createOscillator();
      swell.frequency.value = 0.066;
      const swellDepth = context.createGain();
      swellDepth.gain.value = 0.35;
      swell.connect(swellDepth).connect(gain.gain);
      swell.start();
      sources.push(swell);
      gain.gain.value = 0.65;
    }
    return { sources, gain, nodes };
  }

  if (scene === 'night') {
    const lowpass = context.createBiquadFilter();
    lowpass.type = 'lowpass';
    lowpass.frequency.value = 420;
    const mix = context.createGain();
    mix.gain.value = 0.5;
    for (const [hz, type, level] of [
      [110, 'sine', 0.5],
      [164.81, 'sine', 0.28],
      [55, 'triangle', 0.22],
    ] as Array<[number, OscillatorType, number]>) {
      const osc = context.createOscillator();
      osc.type = type;
      osc.frequency.value = hz;
      const oscGain = context.createGain();
      oscGain.gain.value = level;
      osc.connect(oscGain).connect(mix);
      osc.start();
      sources.push(osc);
      nodes.push(oscGain);
    }
    mix.connect(lowpass).connect(gain);
    nodes.push(lowpass, mix);

    const drift = context.createOscillator();
    drift.frequency.value = 0.028;
    const driftDepth = context.createGain();
    driftDepth.gain.value = 0.12;
    drift.connect(driftDepth).connect(gain.gain);
    drift.start();
    sources.push(drift);
    gain.gain.value = 0.8;
    return { sources, gain, nodes };
  }

  // breath: a swell every ten seconds, i.e. six breaths a minute.
  const lowpass = context.createBiquadFilter();
  lowpass.type = 'lowpass';
  lowpass.frequency.value = 900;
  const mix = context.createGain();
  mix.gain.value = 0.4;
  for (const [hz, level] of [
    [174.61, 0.5],
    [261.63, 0.24],
  ] as Array<[number, number]>) {
    const osc = context.createOscillator();
    osc.type = 'sine';
    osc.frequency.value = hz;
    const oscGain = context.createGain();
    oscGain.gain.value = level;
    osc.connect(oscGain).connect(mix);
    osc.start();
    sources.push(osc);
    nodes.push(oscGain);
  }
  mix.connect(lowpass).connect(gain);
  nodes.push(lowpass, mix);

  const pace = context.createOscillator();
  pace.frequency.value = 1 / 10;
  const paceDepth = context.createGain();
  paceDepth.gain.value = 0.42;
  pace.connect(paceDepth).connect(gain.gain);
  pace.start();
  sources.push(pace);
  gain.gain.value = 0.58;
  return { sources, gain, nodes };
}

export class AmbientEngine {
  private context: AudioContext | null = null;
  private master: GainNode | null = null;
  private analyser: AnalyserNode | null = null;
  private buffer: AudioBuffer | null = null;
  private current: BuiltScene | null = null;
  private currentScene: SceneId | null = null;
  private settings: AudioSettings = { ...DEFAULT_SETTINGS };
  private state: EngineState = 'idle';
  /** While true the master stays silent, whatever the volume slider says. */
  private recording = false;
  private hiddenPause = false;
  private frame: Float32Array<ArrayBuffer> | null = null;
  private listeners = new Set<() => void>();
  private chimesPlayed = 0;
  private onVisibility: (() => void) | null = null;
  private onStateChange: (() => void) | null = null;

  getState(): EngineState {
    return this.state;
  }

  isPlaying(): boolean {
    return this.state === 'running' && this.current !== null;
  }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private emit(): void {
    for (const listener of this.listeners) listener();
  }

  /** True when the browser can play generated audio at all. */
  static isSupported(): boolean {
    if (typeof window === 'undefined') return false;
    const Ctor =
      (window as unknown as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext })
        .AudioContext ??
      (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    return typeof Ctor === 'function';
  }

  /**
   * Must be called from inside a user gesture — iOS only unlocks an
   * AudioContext created or resumed in the same tick as the tap.
   */
  async start(settings: AudioSettings): Promise<void> {
    if (!AmbientEngine.isSupported()) {
      this.state = 'unsupported';
      this.emit();
      return;
    }
    this.settings = normalizeSettings(settings);
    this.state = 'starting';
    this.emit();

    try {
      const context = this.context ?? new AudioContext();
      this.context = context;
      if (!this.master) {
        const master = context.createGain();
        master.gain.setValueAtTime(0, context.currentTime);
        const analyser = context.createAnalyser();
        analyser.fftSize = 2048;
        // Analyser sits after the master gain and before the speakers, so the
        // meter reflects what the app is actually sending out.
        master.connect(analyser);
        analyser.connect(context.destination);
        this.master = master;
        this.analyser = analyser;
        this.frame = new Float32Array(analyser.fftSize);
      }
      this.buffer ??= makeNoiseBuffer(context);

      if (context.state !== 'running') await context.resume();
      this.attachPageHooks();

      this.setScene(this.settings.scene, 0);
      this.applyVolume(0);
      this.state = context.state === 'running' ? 'running' : 'suspended';
      this.hiddenPause = false;
      this.emit();
    } catch {
      this.state = 'error';
      this.emit();
    }
  }

  /** Fade out and stop the scene, keeping the context for a quick restart. */
  stop(fadeSeconds = FADE_OUT): void {
    const context = this.context;
    if (!context || !this.master) {
      this.state = 'idle';
      this.emit();
      return;
    }
    const when = context.currentTime;
    this.master.gain.cancelScheduledValues(when);
    this.master.gain.setTargetAtTime(0, when, fadeSeconds / 3);
    this.teardownScene(fadeSeconds);
    this.state = 'idle';
    this.emit();
  }

  private teardownScene(fadeSeconds: number): void {
    const context = this.context;
    const scene = this.current;
    this.current = null;
    this.currentScene = null;
    if (!context || !scene) return;
    const when = context.currentTime;
    scene.gain.gain.cancelScheduledValues(when);
    scene.gain.gain.setTargetAtTime(0, when, Math.max(0.05, fadeSeconds / 3));
    const stopAt = when + fadeSeconds + 0.35;
    for (const source of scene.sources) {
      try {
        source.stop(stopAt);
      } catch {
        // Already stopped: nothing to do.
      }
    }
    window.setTimeout(() => {
      for (const node of scene.nodes) {
        try {
          node.disconnect();
        } catch {
          // Already disconnected.
        }
      }
    }, (fadeSeconds + 0.5) * 1000);
  }

  setScene(id: SceneId, fadeSeconds = FADE_IN): void {
    const context = this.context;
    const master = this.master;
    const buffer = this.buffer;
    if (!context || !master || !buffer) return;
    if (this.currentScene === id && this.current) return;

    this.teardownScene(Math.min(fadeSeconds, 0.6));

    const built = buildScene(context, buffer, id);
    // Start at silence and ramp in, while the previous scene ramps out. No
    // waveform is ever started or stopped at a non-zero level.
    built.gain.gain.setValueAtTime(0.0001, context.currentTime);
    built.gain.gain.setTargetAtTime(1, context.currentTime, Math.max(0.15, fadeSeconds / 3));
    built.gain.connect(master);
    this.current = built;
    this.currentScene = id;
    this.settings = { ...this.settings, scene: id };
    this.emit();
  }

  setVolume(volume: number): void {
    this.settings = { ...this.settings, volume: clampVolume(volume) };
    this.applyVolume(RAMP_TAU);
    this.emit();
  }

  setChimes(chimes: boolean): void {
    this.settings = { ...this.settings, chimes };
    this.emit();
  }

  getSettings(): AudioSettings {
    return { ...this.settings };
  }

  private applyVolume(tau: number): void {
    const context = this.context;
    const master = this.master;
    if (!context || !master) return;
    const target = this.recording ? 0 : gainForVolume(this.settings.volume);
    const when = context.currentTime;
    master.gain.cancelScheduledValues(when);
    if (tau <= 0) {
      master.gain.setValueAtTime(target, when);
      return;
    }
    // Hold the current value so the ramp starts from where we are, not from a
    // scheduled value that never happened.
    master.gain.setValueAtTime(Math.max(master.gain.value, 0.0001), when);
    master.gain.setTargetAtTime(target, when, tau);
  }

  /** Short, quiet cue. Never the only feedback for an action. */
  chime(kind: ChimeKind): void {
    const context = this.context;
    const master = this.master;
    if (!context || !master || !this.settings.chimes) return;
    if (context.state !== 'running') return;
    this.chimesPlayed += 1;
    const spec = CHIMES[kind];
    const when = context.currentTime;
    const level = Math.max(0.02, gainForVolume(this.settings.volume)) * 0.9;
    for (const partial of spec.partials) {
      const osc = context.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = partial.hz;
      const gain = context.createGain();
      const peak = level * partial.gain * 0.5;
      gain.gain.setValueAtTime(0.0001, when);
      gain.gain.linearRampToValueAtTime(peak, when + 0.012);
      gain.gain.exponentialRampToValueAtTime(0.0001, when + spec.decay);
      osc.connect(gain).connect(master);
      osc.start(when);
      osc.stop(when + spec.decay + 0.05);
      osc.onended = () => {
        try {
          gain.disconnect();
        } catch {
          // Already gone.
        }
      };
    }
  }

  /** Silence while the microphone is open, so nothing bleeds into a clip. */
  suspendForRecording(): void {
    const context = this.context;
    this.recording = true;
    if (!context || !this.master) return;
    this.master.gain.cancelScheduledValues(context.currentTime);
    this.master.gain.setTargetAtTime(0, context.currentTime, 0.05);
  }

  resumeAfterRecording(): void {
    this.recording = false;
    if (this.state !== 'running' || this.hiddenPause) return;
    this.applyVolume(0.2);
  }

  isRecording(): boolean {
    return this.recording;
  }

  private handleVisibility = (): void => {
    const context = this.context;
    if (!context) return;
    if (document.hidden) {
      if (this.state === 'running') {
        const when = context.currentTime;
        this.master?.gain.cancelScheduledValues(when);
        this.master?.gain.setTargetAtTime(0, when, 0.05);
        void context.suspend();
        this.hiddenPause = true;
      }
      return;
    }
    // Coming back: stay silent until the user asks again.
    if (this.hiddenPause) {
      this.hiddenPause = false;
      this.state = 'suspended';
      this.emit();
    }
  };

  private handleContextState = (): void => {
    const context = this.context;
    if (!context) return;
    if (context.state === 'running') {
      if (this.state === 'suspended' && !this.hiddenPause) {
        this.state = 'running';
        this.emit();
      }
      return;
    }
    if (context.state === 'interrupted' || context.state === 'suspended') {
      if (this.state === 'running') {
        this.state = 'suspended';
        this.emit();
      }
    }
  };

  private attachPageHooks(): void {
    if (typeof document === 'undefined' || this.onVisibility) return;
    this.onVisibility = this.handleVisibility;
    this.onStateChange = this.handleContextState;
    document.addEventListener('visibilitychange', this.onVisibility);
    this.context?.addEventListener('statechange', this.onStateChange);
  }

  /** RMS of the master bus, 0–1. Development and test use only. */
  meter(): number {
    const analyser = this.analyser;
    const frame = this.frame;
    if (!analyser || !frame) return 0;
    analyser.getFloatTimeDomainData(frame);
    let sum = 0;
    for (let i = 0; i < frame.length; i += 1) {
      const value = frame[i] ?? 0;
      sum += value * value;
    }
    return Math.sqrt(sum / frame.length);
  }

  snapshot(): EngineSnapshot {
    return {
      state: this.state,
      contextState: this.context?.state ?? 'none',
      scene: this.currentScene,
      volume: this.settings.volume,
      gain: this.master?.gain.value ?? 0,
      chimes: this.settings.chimes,
      meter: this.meter(),
      sampleRate: this.context?.sampleRate ?? 0,
      hiddenPause: this.hiddenPause,
      chimesPlayed: this.chimesPlayed,
    };
  }

  close(): void {
    if (typeof document !== 'undefined' && this.onVisibility) {
      document.removeEventListener('visibilitychange', this.onVisibility);
    }
    if (this.onStateChange) this.context?.removeEventListener('statechange', this.onStateChange);
    this.onVisibility = null;
    this.onStateChange = null;
    this.teardownScene(0.05);
    void this.context?.close();
    this.context = null;
    this.master = null;
    this.analyser = null;
    this.buffer = null;
    this.frame = null;
    this.state = 'idle';
    this.emit();
  }
}

/* audio-guard:start */
/**
 * Guard against the one thing that would break the privacy promise: fetching
 * audio from somewhere. Kept as a function so a test can run it.
 *
 * The markers around this block exist because the patterns below are the very
 * strings the test searches for; everything outside the markers is scanned.
 */
export function assertNoRemoteAudio(source: string): { ok: boolean; reason?: string } {
  if (/\bfetch\s*\(|XMLHttpRequest|howler|new Audio\s*\(|\.mp3|\.ogg|\.wav|https?:\/\//i.test(source)) {
    return { ok: false, reason: 'The audio engine must synthesise sound, never load it.' };
  }
  return { ok: true };
}
/* audio-guard:end */
